import json
n=19
centers=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
marks={(2,6):3,(3,5):3,(3,6):8,(3,7):3,(4,6):3,(3,13):3,(4,12):3,(4,13):4,(4,14):3,(5,13):3,(9,8):3,(10,7):3,(10,9):3,(11,8):3,(11,14):3,(12,13):3,(12,14):1,(12,15):3,(13,14):3,(13,3):3,(14,2):3,(14,3):2,(14,4):3,(15,3):3}
g=[[0]*n for _ in range(n)]
# Create full-color lines with vertical lines drawn last, then restore original 3 arms and centers.
for (r,c),v in marks.items(): g[r][c]=v
for r,c,v in centers:
 for j in range(n):
  if g[r][j]==0:g[r][j]=v
for r,c,v in centers:
 for i in range(n):
  if g[i][c]==0:g[i][c]=v
# Vertical lines own crossings unless they were original marks.
for r,_,_ in centers:
 for _,c,v in centers:
  if marks.get((r,c),0)==0:g[r][c]=v
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

